"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["43811"],{15193(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.documento_exigido.modelo_nao_encontrado","status":422,"titulo":"O modelo de documento citado n\xe3o existe neste processo"},"descricao":{"codigo":"uniplus.selecao.documento_exigido.modelo_nao_encontrado","requisitos":[],"oQueAconteceu":["Uma exig\xeancia pode citar um modelo de documento cadastrado no processo. O modelo citado n\xe3o foi\\nencontrado: ou n\xe3o existe, ou pertence a outro processo, e um processo s\xf3 usa os modelos que\\ns\xe3o dele.","Ao salvar o rascunho, a cita\xe7\xe3o n\xe3o resolvida gera diagn\xf3stico com o ponteiro `/documentosExigidos/exigencias/{i}/modeloId`; a publica\xe7\xe3o recusa a configura\xe7\xe3o enquanto a causa persistir. Ao importar em outro rascunho, envie o arquivo novamente para o novo dono e atualize a cita\xe7\xe3o.","Ao salvar o rascunho, o modelo citado \xe9 procurado diretamente no cadastro. Na montagem de cada\\nexig\xeancia, a confer\xeancia do modelo vem depois das confer\xeancias de forma, tipo de documento,\\ncondi\xe7\xf5es e bases legais da pr\xf3pria exig\xeancia."],"comoResolver":["Cadastre o modelo neste processo e cite o identificador dele, ou retire a refer\xeancia ao modelo\\nda exig\xeancia. Depois, envie a defini\xe7\xe3o de novo."],"ondeAparece":["Grava\xe7\xe3o do rascunho do processo seletivo","Defini\xe7\xe3o de documentos exigidos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Documento exigido"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);